{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "SQ 29852, a phosphoryl-containing ACE inhibitor, showed 66% oral bioavailability in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Quinapril absolute bioavailability was 51.7% after a 2.5 mg oral dose in humans, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Perindopril absolute oral bioavailability was about 75% in patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Moexipril oral bioavailability was 22% in healthy volunteers; although described as low relative to other ACE inhibitors, it is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "The active moiety from the prodrug quinapril had 46-52% oral bioavailability in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All available human pharmacokinetic records for related ACE inhibitors report oral bioavailability values above the 20% threshold (22-95%), so the query is predicted to have high absolute oral bioavailability at the F >= 20% endpoint.",
  "evidence_gaps": [
    "No direct experimental measurement for the query molecule itself is available.",
    "No retrieved record reports a value below 20%, so there is no contrasting low-bioavailability example in the evidence set.",
    "Some records are not explicitly labeled as absolute bioavailability or use different calculation methods."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

